1	/****************************************************************************
2	 * board/bk7258-devkit/src/bk7258_console.c
3	 *
4	 * CP init entry (CONFIG_INIT_ENTRYPOINT).  UART0 stays on the CP, which
5	 * owns the AP lifecycle and the early boot log.  With
6	 * BK7258_CONSOLE_AUTO_AP the console is handed to the AP NSH through cu
7	 * once the AP scheduler is running; "~." in cu falls back to the CP NSH,
8	 * and "cu" from there goes back.  The init task is the only console
9	 * reader at any time: cu first, then nsh_main.
10	 ****************************************************************************/
11	
12	#include <nuttx/config.h>
13	
14	#include <sched.h>
15	#include <stdbool.h>
16	#include <stdio.h>
17	#include <unistd.h>
18	
19	#include <sys/boardctl.h>
20	#include <sys/wait.h>
21	
22	#include <arch/chip/bk7258_ap_boot.h>
23	
24	int nsh_main(int argc, FAR char *argv[]);
25	
26	#ifdef CONFIG_BK7258_CONSOLE_AUTO_AP
27	int cu_main(int argc, FAR char *argv[]);
28	
29	#define BK7258_CONSOLE_POLL_MS 200
30	
31	/* bk7258_ap_control.c: the AP of this boot runs its scheduler and has
32	 * heartbeat at least twice (its health thread starts just before the AP
33	 * NSH). */
34	
35	bool bk7258_ap_is_running(void);
36	
37	static void bk7258_console_attach_ap(void)
38	{
39	  FAR char *argv[] =
40	  {
41	    "cu", "-l", "/dev/ttyAP", NULL
42	  };
43	
44	  int polls = 0;
45	  pid_t pid;
46	
47	  while (!bk7258_ap_is_running())
48	    {
49	      if (++polls * BK7258_CONSOLE_POLL_MS >
50	          CONFIG_BK7258_CONSOLE_AUTO_AP_TIMEOUT * 1000)
51	        {
52	          printf("\n[console] AP not running after %d s, "
53	                 "staying on the CP NSH\n",
54	                 CONFIG_BK7258_CONSOLE_AUTO_AP_TIMEOUT);
55	          return;
56	        }
57	
58	      usleep(BK7258_CONSOLE_POLL_MS * 1000);
59	    }
60	
61	  printf("\n[console] attached to the AP NSH; "
62	         "\"~.\" returns to the CP NSH, \"cu\" comes back\n");
63	
64	  /* A task of its own: cu installs a SIGINT handler it never restores,
65	   * which must not outlive it into the CP NSH. */
66	
67	  pid = task_create("cu", CONFIG_SYSTEM_CUTERM_PRIORITY,
68	                    CONFIG_SYSTEM_CUTERM_STACKSIZE, cu_main, &argv[1]);
69	  if (pid < 0)
70	    {
71	      printf("[console] cu start failed: %d\n", pid);
72	      return;
73	    }
74	
75	  waitpid(pid, NULL, 0);
76	}
77	#endif
78	
79	int bk7258_cp_init_main(int argc, FAR char *argv[])
80	{
81	#ifdef CONFIG_BK7258_CONSOLE_AUTO_AP
82	  /* What nsh_main would do first (procfs, LCD), so the CP is fully set up
83	   * while the console sits on the AP. */
84	
85	  boardctl(BOARDIOC_INIT, 0);
86	  bk7258_console_attach_ap();
87	#endif
88	
89	  return nsh_main(argc, argv);
90	}
